<section class="print-report"><header class="flex items-center justify-between border-b-2 border-primary pb-5"><div class="flex items-center gap-4"><img src="<?= e(asset('images/logo.webp')) ?>" alt="Logo Tirtanadi" class="h-16 w-16 object-contain"><div><p class="text-lg font-bold text-primary">PERUMDA TIRTANADI</p><p class="text-sm text-slate-600">Cabang Medan Denai</p></div></div><div class="text-right text-xs text-slate-500">Dicetak: <?= e(formatTanggalWaktu(date('Y-m-d H:i:s'))) ?></div></header><div class="py-7 text-center"><h1 class="text-xl font-bold uppercase text-slate-900">Laporan Status Pemutusan dan Daftar Ulang</h1><p class="mt-1 text-sm text-slate-600">Pelanggan Nonaktif Tirtanadi Cabang Medan Denai</p><p class="mt-3 text-xs text-slate-500">Filter: <?= e($filters['periode'] ? 'dibuat sejak ' . formatTanggal($filters['periode']) : 'semua periode') ?><?= $filters['status'] ? ' · Status ' . e($filters['status']) : '' ?><?= $filters['jenis'] ? ' · ' . e($filters['jenis']) : '' ?><?= $filters['verifikasi'] ? ' · ' . e($filters['verifikasi']) : '' ?></p></div><table class="w-full border-collapse text-left text-xs"><thead><tr class="bg-slate-100"><th class="border border-slate-300 p-2">No</th><th class="border border-slate-300 p-2">NPA</th><th class="border border-slate-300 p-2">Nama / Alamat</th><th class="border border-slate-300 p-2">Status</th><th class="border border-slate-300 p-2">Lama Nonaktif</th><th class="border border-slate-300 p-2">Tindakan / Biaya</th><th class="border border-slate-300 p-2">Daftar Ulang</th></tr></thead><tbody><?php foreach ($rows as $i => $row): $kategori = kategoriStatus($row); ?><tr><td class="border border-slate-300 p-2 align-top"><?= $i + 1 ?></td><td class="border border-slate-300 p-2 align-top font-mono"><?= e($row['npa']) ?></td><td class="border border-slate-300 p-2 align-top"><b><?= e($row['nama_pelanggan']) ?></b><br><?= e($row['alamat']) ?></td><td class="border border-slate-300 p-2 align-top"><?= e($kategori['label']) ?></td><td class="border border-slate-300 p-2 align-top"><?= $kategori['key'] === 'aktif' ? '—' : e((string) $kategori['days']) . ' hari' ?></td><td class="border border-slate-300 p-2 align-top"><?= e($row['jenis_tindakan'] ?: '—') ?><br><?= $row['biaya_tindakan'] !== null ? e(formatRupiah($row['biaya_tindakan'])) : '' ?></td><td class="border border-slate-300 p-2 align-top"><?= e($row['status_verifikasi'] ?: 'Belum daftar') ?><br><?= $row['biaya_daftar_ulang'] !== null ? e(formatRupiah($row['biaya_daftar_ulang'])) : '' ?></td></tr><?php endforeach; ?></tbody></table><footer class="mt-12 grid grid-cols-2 text-center text-sm"><div><p>Mengetahui,</p><p class="mt-16 font-semibold">Pimpinan Cabang</p></div><div><p>Medan Denai, <?= e(formatTanggal(date('Y-m-d'))) ?></p><p class="mt-16 font-semibold"><?= e(Auth::user()['nama_lengkap']) ?></p><p class="text-xs text-slate-500"><?= e(Auth::user()['role']) ?></p></div></footer></section>
